function parseSarVv(s){const m=(s||'').match(/([-+]?\d+\.?\d*)/);return m?parseFloat(m[1]):-12;}function sarMoisture(v){return v>-12?'Alta 68%':v>=-16?'Media 42%':'Baja 21%';}function ndviProxy(l,s){const a=Math.abs(l);let v=a<10?.62:a<25?.38:a<45?.52:a<60?.32:.18;if(s==='mining')v-=.18;else if(s==='energy')v-=.22;else if(s==='fishing')v=.04;return Math.max(.02,Math.min(.85,+v.toFixed(4)));}function calcFSS(s,d){const{temp:t,precip7d:p,soil:sl,wind:w,seismic:e,thermal:h,wave:wa,ndvi:n}=d;let f;if(s==='energy'){f=55+e*-2.5+(h>5?-8:h>0?-3:4)+(w>60?-5:0)+(t>40?-5:0);}else if(s==='agriculture'){f=38+n*58+(sl?sl*12:5)+(p>20?8:p>5?4:-4)+e*-2+(t>38?-8:t<-5?-5:0);}else if(s==='fishing'){f=62+(wa>5?-22:wa>3?-12:wa>1.5?-5:8)+(w>65?-12:w>45?-5:4)+e*-4;}else{f=55+e*-5+(h>3?-7:0)+(w>70?-5:0)+(t>40?-3:0);}return Math.round(Math.max(18,Math.min(94,f)));}
